  ('bioetanol-maiz-14-14098', 'bioetanol-maiz', '14', '14098', TRUE, 'procesamiento', 2026, 'se-bioetanol-empresas-csv', 'bioetanol.csv: plantas de bioetanol de maíz en Córdoba (Río Cuarto, Villa María, Alejandro Roca)', 'alta'),
