  ('soda-solvay-62-62077', 'soda-solvay', '62', '62077', TRUE, 'sintesis', 2025, 'usgs-mcs-2025-soda-ash', 'USGS MCS 2025 Soda Ash + operación Solvay Punta Delgado (San Antonio Oeste, Río Negro)', 'alta'),
  ('cal-industrial-70-70105', 'cal-industrial', '70', '70105', TRUE, 'procesamiento', 2026, 'caleras-sj-web-2026', 'calerassanjuan.com Polo Calero Los Berros (Depto. Sarmiento, San Juan)', 'alta'),
  ('oro-plata-78-78042', 'oro-plata', '78', '78042', TRUE, 'refinacion', 2026, 'cerro-vanguardia-web-2026', 'cerrovanguardia.com.ar Yacimiento y planta doré (Depto. Magallanes, Santa Cruz)', 'alta'),
