  ('celulosa-kraft-54-54063', 'celulosa-kraft', '54', '54063', TRUE, 'procesamiento', 2026, 'arauco-web-2026', 'arauco.com Planta de Celulosa Puerto Esperanza (Depto. Iguazú, Misiones)', 'alta'),
