INSERT INTO public.empresas (empresa_id, razon_social, tipo_capital, sitio_web_oficial, hechos_verificables, anio, fuente_id, cita_ubicacion, confianza) VALUES
  ('aluar-saic', 'Aluar Aluminio Argentino S.A.I.C.', 'nacional', 'https://www.aluar.com.ar/', 'Único productor de aluminio primario en Argentina (CUIT 30-52278060-6). Creada en 1970, cotiza en la Bolsa de Comercio de Buenos Aires bajo fiscalización de CNV desde 1980. Controla el 60,20% de Hidroeléctrica Futaleufú S.A. y opera un Parque Eólico propio en Puerto Madryn (ampliación en curso hacia 582 MW). Dotación al 30/06/2025: 2.330 personas (1.582 en División Aluminio Primario).', 2025, 'aluar-eeff-2025', 'Memoria 2025 pág. 2 y 10; Estados Financieros Nota 1 pág. 8 y Nota 2.3.1 pág. 11', 'alta'),
  ('rio-tinto-litio-ar', 'Rio Tinto Lithium Argentina (operaciones Fénix, Olaroz y Rincón)', 'mixto', 'https://www.riotinto.com/en/operations/south-america/fenix', 'Opera tres complejos de salmuera en la Puna argentina: Fénix en Salar del Hombre Muerto (Catamarca, 100% propia, activa desde 1997, 32.000 t/año LCE), Olaroz en Jujuy (66,5% en JV con Toyota Tsusho y participación provincial, activa desde 2014) y el proyecto Rincón en Salta (planta inicial de 3.000 t/año con primer litio en noviembre 2024 y ampliación aprobada hacia 60.000 t/año).', 2026, 'riotinto-fenix-2026', 'riotinto.com/en/operations/south-america/fenix (100% Rio Tinto, 32 ktpa LCE, inicio 1997)', 'alta'),
  ('profertil-sa', 'Profertil S.A.', 'mixto', 'https://www.profertil.com.ar/', 'Único productor integrado de urea granulada y amoníaco a gran escala en Argentina (CUIT 30-69157651-1). Inició producción comercial en enero de 2001 en Zona Cangrejales del Puerto de Bahía Blanca (predio de 605.110 m2). Capacidad nominal: 1.320.000 t/año de urea granulada y 790.000 t/año de amoníaco; contratos de gas natural hasta 2.500.000 m3/día. Al 31/12/2025 su capital pertenece 90% al Grupo Adecoagro y 10% a ACA (hasta dic. 2025: 50% YPF y 50% Nutrien).', 2025, 'profertil-eecc-2025', 'EECC-31-12-25.pdf pág. 4, 6, 78-79 y 88 (Memoria y Reseña Informativa)', 'alta'),
  ('buyatti-saica', 'Buyatti S.A.I.C.A.', 'nacional', 'https://buyatti.com.ar/', 'Complejo agroindustrial con planta de desmote y procesamiento de semillas de algodón en Las Breñas (Depto. 9 de Julio, Chaco) y plantas oleaginosas en Reconquista y Puerto General San Martín (Santa Fe).', 2026, 'buyatti-web-2026', 'buyatti.com.ar (desmote y procesamiento de semilla de algodón, Las Breñas, Chaco)', 'alta'),
  ('renova-sa', 'Renova S.A.', 'mixto', 'https://renova.com.ar/', 'Opera en Timbúes (Depto. San Lorenzo, Santa Fe) uno de los mayores complejos de molienda de soja del mundo (32.400 t/día, recepción 60.000 t/día camiones y 15.000 t/día barcazas), además de planta de biodiésel (1.450 t/día) y glicerina refinada (270 t/día) en San Lorenzo.', 2026, 'renova-web-2026', 'renova.com.ar (Planta Timbúes 32.400 t/día molienda; Planta San Lorenzo 1.450 t/día biodiésel)', 'alta'),
  ('molinos-agro-sa', 'Molinos Agro S.A.', 'nacional', 'https://molinosagro.com.ar/', 'Opera el complejo industrial y Puerto San Benito en San Lorenzo (Santa Fe) con capacidad de molienda declarada de 6.000.000 t/año de poroto de soja, embarcando 5% del comercio mundial de harina y 4% del aceite de soja.', 2026, 'molinosagro-web-2026', 'molinosagro.com.ar/nuestro-negocio/ (Puerto San Benito: 6.000.000 t/año molienda soja)', 'alta'),
  ('dow-pbbpolisur', 'Dow Argentina (PBBPolisur S.R.L.)', 'extranjero', 'https://ar.dow.com/es-ar.html', 'Opera en Bahía Blanca el complejo petroquímico más grande de América Latina, con seis plantas productivas (2 de etileno y 4 de polietileno LDPE, LLDPE y HDPE).', 2026, 'dow-argentina-web-2026', 'ar.dow.com/es-ar.html (seis plantas: 2 de etileno y 4 de polietileno en Bahía Blanca)', 'alta'),
  ('unipar-indupa', 'Unipar Indupa S.A.I.C.', 'extranjero', 'https://unipar.com/es/acerca-de-unipar', 'Opera en el Polo Petroquímico de Bahía Blanca el complejo cloro-álcali y vinílico que elabora cloro, soda cáustica y policloruro de vinilo (PVC).', 2026, 'unipar-acerca-2026', 'unipar.com/es/acerca-de-unipar (unidad Bahía Blanca: cloro, soda cáustica y PVC)', 'alta'),
  ('ypf-sa', 'YPF S.A.', 'mixto', 'https://inversores.ypf.com/', 'Principal compañía integrada de energía de Argentina con participación estatal mayoritaria (51%) y cotización en BYMA (YPFD) y NYSE (YPF). Opera los complejos industriales de Plaza Huincul (metanol desde gas natural y refinería en Neuquén) y Luján de Cuyo (refinación y propileno en Mendoza).', 2026, 'ypf-inversores-2026', 'inversores.ypf.com (operaciones industriales Plaza Huincul y Luján de Cuyo)', 'alta'),
  ('petrocuyo-saic', 'Petrocuyo S.A.I.C.', 'nacional', 'https://www.petrocuyo.com/', 'Productor líder de polipropileno en Argentina con planta industrial en el Polo Petroquímico de Luján de Cuyo (Mendoza), abastecida por corrientes de propileno de refinería.', 2026, 'petrocuyo-web-2026', 'petrocuyo.com (operaciones de polipropileno en Luján de Cuyo, Mendoza)', 'alta'),
  ('bio4-argentina', 'Bioetanol Río Cuarto S.A. (Bio4)', 'nacional', 'https://bio4.com.ar/', 'Productora cordobesa pionera de bioetanol anhidro a partir de maíz en Río Cuarto (Depto. Río Cuarto, Córdoba), registrada en la Secretaría de Energía con coproducción de burlanda húmeda/seca (WDGS/DDGS) y energía renovable.', 2026, 'bio4-web-2026', 'bio4.com.ar y registro Secretaría de Energía bioetanol.csv (Río Cuarto, Córdoba)', 'alta'),
  ('aca-bio', 'ACA Bio Cooperativa Limitada', 'nacional', 'https://www.acabio.com.ar/', 'Biorrefinería cooperativa ubicada en Villa María (Depto. General San Martín, Córdoba) que industrializa maíz en bioetanol anhidro para mezcla en naftas, burlanda proteica y CO2 alimenticio.', 2026, 'acabio-web-2026', 'acabio.com.ar (biorrefinería Villa María, Córdoba)', 'alta'),
  ('bioenergetica-la-florida', 'Compañía Bioenergética La Florida S.A.', 'nacional', 'https://centroazucarero.com.ar/', 'Destilería y deshidratadora de bioetanol de caña de azúcar ubicada en La Florida (Depto. Cruz Alta, Tucumán), registrada en los cupos oficiales de la Secretaría de Energía dentro del complejo sucroalcoholero tucumano.', 2026, 'se-bioetanol-empresas-csv', 'bioetanol.csv (Compañía Bioenergética La Florida S.A., La Florida, Tucumán)', 'alta'),
  ('alpat-saic', 'Álcalis de la Patagonia S.A.I.C. (ALPAT)', 'nacional', NULL, 'Única planta productora de carbonato de sodio sintético (proceso Solvay) de Sudamérica, localizada en Punta Delgado (San Antonio Oeste, Río Negro), abasteciendo a la industria del vidrio, detergentes y carbonatación de litio.', 2025, 'usgs-mcs-2025-soda-ash', 'USGS MCS 2025 Soda Ash + síntesis Solvay Argentina (San Antonio Oeste)', 'alta'),
  ('caleras-san-juan-sa', 'Caleras San Juan S.A.', 'nacional', 'https://calerassanjuan.com/', 'Complejo industrial calero en Los Berros (Depto. Sarmiento, San Juan) con hornos verticales regenerativos (PFRK) de cal viva (CaO) e hidratada para minería de cobre/litio, siderurgia y exportación a Chile.', 2026, 'caleras-sj-web-2026', 'calerassanjuan.com Sección Operaciones Industriales Los Berros', 'alta'),
  ('cerro-vanguardia-sa', 'Cerro Vanguardia S.A.', 'mixto', 'https://www.cerrovanguardia.com.ar/', 'Operación minera y metalúrgica de oro y plata en el Macizo del Deseado (Depto. Magallanes, Santa Cruz) participada por AngloGold Ashanti (92,5%) y Fomicruz S.E. de la Provincia de Santa Cruz (7,5%).', 2026, 'cerro-vanguardia-web-2026', 'cerrovanguardia.com.ar Información Institucional y Planta Metalúrgica', 'alta'),
  ('newmont-cerro-negro', 'Oroplata S.A. (Cerro Negro · Newmont)', 'extranjero', NULL, 'Complejo minero subterráneo y planta de procesamiento de oro y plata Cerro Negro en el área de Perito Moreno (Depto. Lago Buenos Aires, Santa Cruz), uno de los principales productores auríferos de Argentina.', 2026, 'caem-web-2026', 'caem.com.ar Operaciones metalíferas activas en Santa Cruz', 'alta'),
