  ('litio-salmuera-carbonatacion', 'litio', 'PFD: Evaporación Solar de Salmueras, Purificación y Precipitación de Carbonato de Litio (Puna)', 'ISO 10628 / ASME', '1,00 t de Li2CO3 grado batería (13,53 kmol Li2CO3; 0,188 t Li)', 'Ruta evaporítica de la Puna argentina (Salar de Olaroz, Hombre Muerto y Rincón): bombeo desde acuífero hipersalino (~4.000 msnm), concentración solar con precipitación fraccionada de halita/silvita, remoción química de magnesio, calcio y boro, carbonatación con ceniza de soda (Na2CO3) en caliente, centrifugación y secado.', 'Factor metalúrgico oficial USGS MCS 2025 (1 t Li contenido = 5,323 t LCE; Li2CO3 = 18,79% Li). Operaciones verificadas en fichas oficiales de Olaroz (Jujuy), Fénix (Catamarca) y Rincón (Salta). Caudales hídricos variables por salar figuran como s/d.', 1880, 760, '[{"area_id":"area-100","titulo":"Área 100 · Bombeo y Evaporación Solar","x":224,"y":40,"width":352,"height":665},{"area_id":"area-200","titulo":"Área 200 · Purificación (Mg / Ca / B)","x":594,"y":40,"width":338,"height":665},{"area_id":"area-300","titulo":"Área 300 · Carbonatación con Na2CO3","x":950,"y":40,"width":356,"height":665},{"area_id":"area-400","titulo":"Área 400 · Secado y Grado Batería","x":1324,"y":40,"width":332,"height":665}]'::jsonb, '[{"tag":"P-101","nombre":"Bombeo acuífero de salar","simbolo":"pump","area_id":"area-100","x":318,"y":240,"temperatura_op":"10-20 °C","presion_op":"0,65 bar atm.","reaccion":null,"condicion_critica":"4.000 msnm","descripcion":"Extracción profunda de salmuera rica en LiCl, NaCl, KCl y MgCl2 desde cuencas cerradas de la Puna jujeña, catamarqueña y salteña.","fuente_id":"riotinto-olaroz-2026","cita_ubicacion":"riotinto.com/en/operations/south-america/olaroz"},{"tag":"B-101","nombre":"Piletas de evaporación solar","simbolo":"solar_pond","area_id":"area-100","x":502,"y":240,"temperatura_op":"15-35 °C","presion_op":"0,65 bar","reaccion":null,"condicion_critica":"Li ~0,05 -> 6%","descripcion":"Concentración solar escalonada durante meses utilizando radiación UV y viento seco andino; cosecha periódica de sales descartadas.","fuente_id":"riotinto-olaroz-2026","cita_ubicacion":"riotinto.com/en/operations/south-america/olaroz"},{"tag":"S-101","nombre":"Cosecha de halita y sales K/Mg","simbolo":"separator","area_id":"area-100","x":502,"y":515,"temperatura_op":"15-25 °C","presion_op":"0,65 bar","reaccion":null,"condicion_critica":null,"descripcion":"Precipitación secuencial de NaCl (halita) y silvinita/carnalita antes del envío de salmuera concentrada (~6% Li) a planta química.","fuente_id":"riotinto-olaroz-2026","cita_ubicacion":"riotinto.com/en/operations/south-america/olaroz"},{"tag":"R-201","nombre":"Purificación química Mg y Ca","simbolo":"reactor","area_id":"area-200","x":684,"y":240,"temperatura_op":"40-70 °C","presion_op":"1,0 bar","reaccion":"MgCl2 + Ca(OH)2 -> Mg(OH)2 + CaCl2","condicion_critica":"Cal + Soda","descripcion":"Agregado de lechada de cal y carbonato para precipitar hidróxido de magnesio y carbonato de calcio que contaminarían el litio.","fuente_id":"riotinto-fenix-2026","cita_ubicacion":"riotinto.com/en/operations/south-america/fenix"},{"tag":"V-201","nombre":"Filtro prensa tortas Mg/Ca","simbolo":"filter_baghouse","area_id":"area-200","x":858,"y":515,"temperatura_op":"30-50 °C","presion_op":"3-5 bar","reaccion":null,"condicion_critica":null,"descripcion":"Separación sólido-líquido con lavado para minimizar oclusión de litio en la torta descartada de magnesio y calcio.","fuente_id":"riotinto-fenix-2026","cita_ubicacion":"riotinto.com/en/operations/south-america/fenix"},{"tag":"T-201","nombre":"Pulido e intercambio iónico (B)","simbolo":"column","area_id":"area-200","x":858,"y":240,"temperatura_op":"25-45 °C","presion_op":"2-3 bar","reaccion":null,"condicion_critica":"Mg/Ca < 50 ppm","descripcion":"Resinas selectivas que remueven trazas finales de calcio, magnesio y boro previo a la reacción de carbonatación.","fuente_id":"riotinto-olaroz-2026","cita_ubicacion":"rioti