  ('biodiesel-transesterificacion-soja', 'biodiesel', 'PFD: Refinación de Aceite, Transesterificación Alcalina, Reciclo de Metanol y Glicerina (Santa Fe)', 'ISO 10628 / ASME', '1,00 t de biodiésel FAME B100 (3,37 kmol éster metílico) en San Lorenzo', 'Proceso continuo representativo del polo San Lorenzo / Gran Rosario: neutralización de acidez libre y secado al vacío de aceite de soja, doble etapa de transesterificación alcalina a 60-65 °C con metanol (exceso molar 6:1) y NaOCH3, separación centrífuga de ésteres y glicerina cruda, columnas de recuperación y rectificación cerrada de metanol, lavado-secado B100 y destilación al vacío de glicerina refinada (99,5%).', 'Esquema basado en US DOE AFDC / NREL y capacidades declaradas de Renova San Lorenzo (1.450 t/día biodiésel, 900 t/día refinado, 270 t/día glicerina). Estequiometría exacta base trioleína (885,43; metanol 32,04; FAME 296,49; glicerina 92,09 kg/kmol).', 1880, 760, '[{"area_id":"area-100","titulo":"Área 100 · Neutralización y Secado","x":224,"y":40,"width":352,"height":665},{"area_id":"area-200","titulo":"Área 200 · Transesterificación y Centrífuga","x":594,"y":40,"width":338,"height":665},{"area_id":"area-300","titulo":"Área 300 · Reciclo Metanol y Lavado B100","x":950,"y":40,"width":356,"height":665},{"area_id":"area-400","titulo":"Área 400 · Refinación de Glicerina","x":1324,"y":40,"width":332,"height":665}]'::jsonb, '[{"tag":"R-101","nombre":"Neutralización de aceite crudo","simbolo":"reactor","area_id":"area-100","x":318,"y":240,"temperatura_op":"70-90 °C","presion_op":"1,0 bar","reaccion":"AGL + NaOH -> jabón + H2O","condicion_critica":"Acidez < 0,1%","descripcion":"Dosificación de ácido fosfórico y soda cáustica para remover gomas y ácidos grasos libres antes de entrar a catálisis básica.","fuente_id":"renova-web-2026","cita_ubicacion":"renova.com.ar (Planta San Lorenzo refinado 900 t/día)"},{"tag":"V-101","nombre":"Secador al vacío de aceite","simbolo":"separator","area_id":"area-100","x":502,"y":240,"temperatura_op":"85-95 °C","presion_op":"0,08 bar","reaccion":null,"condicion_critica":"H2O < 0,05%","descripcion":"Deshidratación al vacío del aceite neutro para impedir hidrólisis del catalizador NaOCH3 durante la síntesis.","fuente_id":"afdc-biodiesel-doe","cita_ubicacion":"US DOE AFDC Biodiesel Production: feedstock drying pretreatment"},{"tag":"R-201","nombre":"Reactores transesterificación","simbolo":"reactor","area_id":"area-200","x":760,"y":240,"temperatura_op":"60-65 °C","presion_op":"1,5 bar","reaccion":"C57H104O6 + 3 CH4O -> 3 C19H36O2 + C3H8O3","condicion_critica":"Exceso MeOH 6:1","descripcion":"Dos etapas continuas en serie con metanol y metilato de sodio para superar conversión >99% hacia ésteres metílicos FAME.","fuente_id":"afdc-biodiesel-doe","cita_ubicacion":"US DOE AFDC Biodiesel Production: base-catalyzed transesterification"},{"tag":"S-201","nombre":"Centrífuga de fases FAME/Glic.","simbolo":"centrifuge","area_id":"area-200","x":760,"y":515,"temperatura_op":"55-60 °C","presion_op":"1,2 bar","reaccion":null,"condicion_critica":"Doble densidad","descripcion":"Separa continuamente la fase liviana rica en FAME (0,88 g/cm3) de la fase pesada de glicerina cruda (1,05-1,15 g/cm3).","fuente_id":"afdc-biodiesel-doe","cita_ubicacion":"US DOE AFDC Biodiesel Production: phase separation"},{"tag":"T-301","nombre":"Columna flash recup. metanol","simbolo":"column","area_id":"area-300","x":1044,"y":240,"temperatura_op":"80-110 °C","presion_op":"0,2-0,4 bar","reaccion":null,"condicion_critica":"Reciclo MeOH","descripcion":"Despoja al vacío el exceso de metanol (3:1 molar excedente) disuelto en la fase éster y en la glicerina cruda.","fuente_id":"afdc-biodiesel-doe","cita_ubicacion":"US DOE AFDC Biodiesel Production: methanol recovery"},{"tag":"T-302","nombre":"Rectificadora de metanol","simbolo":"column","area_id":"area-300","x":1044,"y":515,"temperatura_op":"65-75 °C","presion_op":"1,0 bar","reaccion":null,"condicion_critica":"MeOH > 99%","descripcion":"Separa el metanol anhidro por cabeza devolviéndolo al reactor R-201 en circuito cerrado.","fuente_id":"afdc-biodiesel-doe","cita_ubicacion":"US DOE AFDC Biodiesel Production: methanol rectification & reuse"},{"tag":"V-301","nombre":"Lavado y secado al vacío B100","simbolo":"separator","area_id":"area-300","x":1228,"y":240,"temperatura_op":"55-90 °C","presion_op":"0,1-1,0 bar","reaccion":null,"condicion_critica":"FAME > 96,5%","descripcion":"Neutralización, lavado suave (resinas/agua) y secado flash para cumplir norma EN 14214 / ASTM D6751 (<500 ppm H2O) hacia despacho B100.","fuente_id":"afdc-biodiesel-doe","cita_ubicacion":"US DOE AFDC: biodiesel washing, drying & ASTM D6751 / EN 14214"},{"tag":"R-401","nombre":"Acidulación de glicerina cruda","simbolo":"reactor","area_id":"area-400","x":1418,"y":240,"temperatura_op":"50-65 °C","presion_op":"1,0 bar","reaccion":"Jabones + HCl -> AGL + NaCl","condicion_critica":"Glic. 80%","descripcion":"Neutraliza el catalizador remanente y rompe jabones recuperando ácidos grasos libres antes de purificar glicerol.","fuente_id":"renova-web-2026","cita_ubicacion":"renova.com.ar (San Lorenzo 270 t/día glicerina refinada)"},{"tag":"V-401","nombre":"Destilación al vacío glicerina","simbolo":"separator","area_id":"area-400","x":1560,"y":515,"temperatura_op":"150-175 °C","presion_op":"0,01-0,03 bar","reaccion":null,"condicion_critica":"USP >= 99,5%","descripcion":"Evaporación de película delgada en alto vacío para evitar descomposición térmica (>200 °C) y pulido con carbón activado.","fuente_id":"renova-web-2026","cita_ubicacion":"renova.com.ar (Planta San Lorenzo glicerina refinada 270 t/día)"}]'::jsonb, '[{"numero":1,"nombre":"Aceite crudo desgomado (de soja)","tipo":"proceso","origen_tag":null,"destino_tag":"R-101","puntos":[[206,240],[286,240]],"flag_pos":[244,240],"especies":"Triglicéridos + AGL (<1%) + fosfátidos","fase":"Líquido","temperatura_c":"35-45","presion_bar":"1,0","flujo_especifico":{"estado":"dato","valor":1.02,"unidad":"t/t